var i=`0855-roti`;var n=`world-0855`;var s=`IN`;var o=`south-asia`;var a=8;var r=50;var h={en:`Roti`,ua:`Роті`};var d={en:`Roti is a India dish made with whole wheat flour. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Роті, страва кухні країни Індія. Основні складники: цільнозернове пшеничне борошно. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var l=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 18 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 18 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:18,i:[[`whole-wheat-flour`,420,`g`],[`water`,255,`ml`],[`table-salt`,5,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 18 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 18 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:18,i:[[`canola-oil`,10,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`ghee`,35,`g`]]}];var u={slug:i,id:n,country:`IN`,region:o,servings:8,minutes:50,title:h,text:d,steps:l};export{s as country,u as default,n as id,r as minutes,o as region,a as servings,i as slug,l as steps,d as text,h as title};